import random


def generate(seed: int = 0) -> list[str]:
    """Cases are equal multisets or have one changed value, and arrays have equal length."""
    r = random.Random(seed)
    cases = [([1, 2, 3, 4], [2, 4, 1, 3])]
    seen = set()
    while len(cases) < 600:
        a = [r.randint(1, 1000) for _ in range(r.randint(1, 50))]
        b = a[:]
        r.shuffle(b)
        if r.randrange(2):
            i = r.randrange(len(b))
            b[i] = b[i] - 1 if b[i] > 1 else b[i] + 1
        key = (tuple(a), tuple(b))
        if key not in seen:
            seen.add(key)
            cases.append((a, b))
    return [f"candidate(target={a!r}, arr={b!r})" for a, b in cases]


